// Slack webhook data validation and formatting
const data = $json;

// Slackからのwebhook dataを検証
if (!data.text && !data.message) {
  return [{
    json: {
      error: true,
      message: 'No text or message provided',
      statusCode: 400
    }
  }];
}

// メッセージテキストを取得
const messageText = data.text || data.message || '';

// ユーザー情報を抽出
const userId = data.user_id || data.user || 'unknown';
const channelId = data.channel_id || data.channel || 'unknown';

// 日本語でのリクエスト内容を整理
const formattedData = {
  userMessage: messageText.trim(),
  userId: userId,
  channelId: channelId,
  timestamp: new Date().toISOString(),
  requestType: 'calendar_assistance',
  language: 'japanese',
  valid: true
};

console.log('Slack bot request received:', formattedData);

return [{
  json: formattedData
}];

// Parse AI response and determine calendar action
const aiResponse = $json.content || $json.text || '';
const userQuery = $('Prepare AI Context').item.json.userQuery.toLowerCase();

// カレンダー操作の種類を判定
let actionType = 'response_only';  // デフォルトは応答のみ
let needsCalendarAccess = false;

// 予定確認・検索のキーワード
if (userQuery.includes('予定') || userQuery.includes('スケジュール') || userQuery.includes('今日') || userQuery.includes('明日') || userQuery.includes('来週')) {
  actionType = 'read_calendar';
  needsCalendarAccess = true;
}

// 予定作成のキーワード
if (userQuery.includes('追加') || userQuery.includes('作成') || userQuery.includes('登録') || userQuery.includes('予約')) {
  actionType = 'create_event';
  needsCalendarAccess = true;
}

// 予定削除・更新のキーワード
if (userQuery.includes('削除') || userQuery.includes('キャンセル') || userQuery.includes('変更') || userQuery.includes('更新')) {
  actionType = 'modify_event';
  needsCalendarAccess = true;
}

const result = {
  aiResponse: aiResponse,
  actionType: actionType,
  needsCalendarAccess: needsCalendarAccess,
  originalQuery: userQuery,
  userId: $('Prepare AI Context').item.json.userId,
  timestamp: new Date().toISOString()
};

console.log('AI response analysis:', result);

return [{
  json: result
}];

// Format calendar events for AI processing
const events = $json.items || [];
const aiData = $('Analyze AI Response').item.json;

// イベント情報を日本語で整形
const formattedEvents = events.map(event => {
  const start = event.start.dateTime || event.start.date;
  const end = event.end.dateTime || event.end.date;

  return {
    title: event.summary || '無題',
    start: new Date(start).toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' }),
    end: new Date(end).toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' }),
    description: event.description || '',
    location: event.location || ''
  };
});

// カレンダーデータとAI応答を組み合わせ
const combinedResponse = {
  aiResponse: aiData.aiResponse,
  calendarEvents: formattedEvents,
  eventCount: formattedEvents.length,
  actionType: aiData.actionType,
  userId: aiData.userId,
  hasEvents: formattedEvents.length > 0
};

console.log('Calendar data formatted:', combinedResponse);

return [{
  json: combinedResponse
}];

