// Format the final response for Slack
const finalResponse = $json.content || $json.text || $('Analyze AI Response').item.json.aiResponse;
const userId = $('Analyze AI Response').item.json.userId;

// Slack用のメッセージフォーマット
const slackMessage = {
  text: finalResponse,
  response_type: 'in_channel',
  blocks: [
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: finalResponse
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `🤖 Slackボット • ${new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' })}`
        }
      ]
    }
  ]
};

console.log('Slack response formatted:', slackMessage);

return [{
  json: {
    ...slackMessage,
    success: true,
    timestamp: new Date().toISOString()
  }
}];

