// Handle OpenAI API errors
const error = $json.error || {};
const originalData = $('Prepare AI Context').item.json;

console.error('OpenAI API Error:', error);

// エラー用の応答メッセージ
const errorResponse = {
  text: 'AI処理中にエラーが発生しました。申し訳ございませんが、しばらく経ってからもう一度お試しください。',
  response_type: 'ephemeral',
  blocks: [
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: '⚠️ AI処理中にエラーが発生しました。申し訳ございませんが、しばらく経ってからもう一度お試しください。'
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `エラー詳細: ${error.message || 'Unknown error'}`
        }
      ]
    }
  ],
  success: false,
  errorType: 'openai_error'
};

return [{
  json: errorResponse
}];

// Handle Google Calendar API errors
const error = $json.error || {};
const aiData = $('Analyze AI Response').item.json;

console.error('Google Calendar API Error:', error);

// カレンダーアクセスエラーの場合はAI応答のみ返す
const fallbackResponse = {
  text: aiData.aiResponse + '\n\n（カレンダー情報の取得中にエラーが発生しましたが、基本的な回答をお返ししています）',
  response_type: 'in_channel',
  blocks: [
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: aiData.aiResponse
      }
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: '⚠️ カレンダー情報の取得中にエラーが発生しましたが、基本的な回答をお返ししています。'
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `🤖 Slackボット • ${new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' })}`
        }
      ]
    }
  ],
  success: true,
  warning: 'calendar_access_failed'
};

return [{
  json: fallbackResponse
}];
